function storeDraft(target:ReviewTarget,draft:Draft,currentUnknown:boolean){const key=draftKey(target);if(!draft.rating&&draft.unknown===currentUnknown)draftStore.delete(key);else draftStore.set(key,{target,draft});if(typeof window!=="undefined")window.dispatchEvent(new Event("recaloop-drafts"))}
