function DeckList({data,setData,open,flash,viewerStudent}:{data:AppData;setData:(d:AppData)=>void;open:(type:TargetType,id:string)=>void;flash:(s:string)=>void;viewerStudent?:Profile|null}){const[query,setQuery]=useState(""),[sort,setSort]=useState<"new"|"name"|"progress">("new"),[importing,setImporting]=useState(false),[error,setError]=useState(""),ownerId=data.profile?.id;const createDeck=async()=>{const title=prompt("デッキ名");if(!title)return;const list=await createWordList({title,subject:null,description:null});setData({...data,wordLists:[...data.wordLists,{...list,item_count:0}]});flash("デッキを作成しました")};const importDeck=async(file:File|null)=>{if(!file)return;setImporting(true);setError("");try{await importRecaloopDeck(file,data,setData,flash)}catch(e){const message=e instanceof Error?e.message:".recaloop の読み込みに失敗しました";console.error("recaloop import failed",e);setError(message)}finally{setImporting(false)}};const entries=[...data.materialDecks.filter(deck=>deck.user_id===ownerId&&!deck.deleted_at).map(deck=>{const items=data.materialNodes.filter(node=>node.deck_id===deck.id&&node.node_type==="item"),count=deck.item_count??items.length,done=items.filter(item=>item.state?.last_rating).length,due=items.filter(item=>!item.state?.is_completed&&item.state?.next_review_date&&item.state.next_review_date<=today()).length;return{type:"material"as const,id:deck.id,title:deck.title,count,due,progress:count?Math.round(done/count*100):0,created_at:deck.created_at}}),...data.wordLists.filter(list=>list.user_id===ownerId&&!list.deleted_at).map(list=>{const cards=data.wordCards.filter(card=>card.list_id===list.id),count=list.item_count??cards.length,done=cards.filter(card=>card.state?.last_rating).length,due=cards.filter(card=>!card.state?.is_completed&&card.state?.next_review_date&&card.state.next_review_date<=today()).length;return{type:"word"as const,id:list.id,title:list.title,count,due,progress:count?Math.round(done/count*100):0,created_at:list.created_at}})].filter(entry=>entry.title.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==="name"?a.title.localeCompare(b.title,"ja"):sort==="progress"?b.progress-a.progress:new Date(b.created_at).getTime()-new Date(a.created_at).getTime());const remove=async(type:TargetType,id:string,title:string)=>{const studentName=viewerStudent?.display_name||"生徒";if(viewerStudent){if(!confirm(`${studentName} さんのデッキ『${title}』を削除しますか？過去の学習履歴は残ります。`))return;await deleteStudentContent(viewerStudent.id,type,id)}else{if(!confirm(`デッキ『${title}』を削除しますか？過去の学習履歴は残ります。`))return;if(type==="material")await deleteMaterialDeck(id);else await deleteWordList(id)}setData(await loadAppData());flash("デッキを削除しました")};return <><PageTitle title="デッキ" sub="階層とカードをまとめて管理" action={!viewerStudent&&<details className="node-menu add-menu"><summary className="primary-button"><Plus size={14}/>{importing?"読み込み中...":"追加"}</summary><div><button onClick={createDeck} disabled={importing}>新規デッキ作成</button><label className={importing?"disabled":""}>.recaloop インポート<input type="file" accept=".recaloop,application/zip" hidden disabled={importing} onChange={e=>importDeck(e.target.files?.[0]||null)}/></label></div></details>}/>{error&&<p className="notice mt-3">{error}</p>}{importing&&<p className="notice mt-3">.recaloop を読み込み中...</p>}<div className="deck-toolbar"><div className="deck-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="デッキを検索"/></div><div className="deck-filters"><select value={sort} onChange={e=>setSort(e.target.value as typeof sort)} className="filter-chip"><option value="new">新しい順</option><option value="name">名前順</option><option value="progress">進捗順</option></select></div></div><div className="deck-list">{entries.map(entry=><article className="deck-list-card" key={`${entry.type}-${entry.id}`}><button onClick={()=>open(entry.type,entry.id)} className="deck-card-content two-line"><span className="deck-title-line"><h3>{entry.title}</h3></span><p>{entry.count}件 ・ 今日{entry.due} ・ 進捗{entry.progress}%</p></button><button onClick={()=>remove(entry.type,entry.id,entry.title)} className="deck-delete"><Trash2 size={14}/>削除</button></article>)}{!entries.length&&<div className="surface p-8 text-center text-sm text-[#71818d]">該当するデッキはありません。</div>}</div></>}

