function AssignmentCreator({student,data,setData,flash}:{student:Profile;data:AppData;setData:(d:AppData)=>void;flash:(s:string)=>void}){const[deck,setDeck]=useState(""),[selected,setSelected]=useState<string[]>([]),[due,setDue]=useState(today()),[picker,setPicker]=useState(false),[loading,setLoading]=useState(false);const decks=studentDeckOptions(data,student.id),targets=studentTargets(data,student.id).filter(t=>!deck||`${t.target_type}:${t.group_id}`===deck),entries=targets.map(t=>({key:`${t.target_type}:${t.id}`,target:t})),deckTitle=deckLabel(decks,deck);const openPicker=async()=>{if(!deck)return;setLoading(true);try{setData(await dataWithDeckContent(data,deck));setPicker(true)}catch(e){flash(e instanceof Error?`問題を読み込めませんでした: ${e.message}`:"問題を読み込めませんでした")}finally{setLoading(false)}};return <section className="surface assignment-create-card"><div className="section-heading"><h2>課題を作成</h2><p>デッキを選んで、問題を選択します</p></div><div className="assignment-create-form"><select className="field select-field" value={deck} onChange={e=>{setDeck(e.target.value);setSelected([]);setPicker(false)}}><option value="">デッキを選択</option>{decks.map(([id,title])=><option key={id} value={id}>{title}</option>)}</select><DateInput value={due} onChange={setDue}/><button className="secondary-button" disabled={!deck||loading} onClick={openPicker}>{loading?"読み込み中...":"問題を選択"}</button><button className="primary-button" disabled={!selected.length} onClick={async()=>{await createAssignment({student_id:student.id,title:deckTitle||"課題",due_date:due,items:selected.map(id=>({target_type:id.startsWith("material:")?"material_item":"word_card",target_id:id.split(":")[1]}))});setData(await loadAppData());flash("課題を作成しました")}}>配布</button></div><p className="text-xs text-[#718398] mt-2">選択済み {selected.length}件</p>{picker&&<SelectableTargetTree entries={entries} selected={selected} setSelected={setSelected} emptyText="デッキ内に選択できる問題がありません。"/>}</section>}
