function OnboardingModal({complete}:{complete:(grade:GradeLevel,school:string)=>Promise<void>}){const[grade,setGrade]=useState<GradeLevel|"">(""),[school,setSchool]=useState("未定"),[saving,setSaving]=useState(false),[error,setError]=useState("");const valid=Boolean(grade&&schools.includes(school));return <div className="onboarding-backdrop"><div className="onboarding-panel"><span className="onboarding-icon"><BookOpen size={21}/></span><p className="eyebrow mt-4">WELCOME TO RECALOOP</p><h1>最初に学習情報を設定</h1><p className="onboarding-copy">あなたに合った学習状況を表示するため、学年と志望校を設定してください。あとから設定画面で変更できます。</p><label>学年<select className="field select-field mt-2" value={grade} onChange={e=>setGrade(e.target.value as GradeLevel)}><option value="">選択してください</option>{gradeLevels.map(item=><option key={item}>{item}</option>)}</select></label><SchoolPicker value={school} onChange={setSchool}/>{error&&<p className="notice">{error}</p>}<button disabled={!valid||saving} onClick={async()=>{if(!grade||!valid)return;setSaving(true);setError("");try{await complete(grade,school)}catch(e){setError(e instanceof Error?e.message:"保存できませんでした");setSaving(false)}}} className="primary-button w-full">{saving?"保存中...":"設定を完了"}</button></div></div>}
